{
  "name": "通用USB设备",
  "name_en": "Generic USB Device",
  "manufacturer": "",
  "description": "通过USB总线连接的通用设备或实验仪器接口对象，可执行控制传输、批量传输和中断传输，并管理端点、接口、配置与描述符读取。适合用于与各类USB连接的实验室设备进行底层通信和枚举。",
  "description_en": "A generic USB-connected device or laboratory instrument interface that supports control, bulk, and interrupt transfers, along with endpoint, interface, configuration, and descriptor management. It is suitable for low-level communication and enumeration of various USB-connected lab devices.",
  "tag_hints": [
    "USB communication",
    "bulk transfer",
    "interrupt transfer",
    "control transfer",
    "endpoint management",
    "USB descriptors",
    "interface configuration"
  ],
  "actions": [
    {
      "action_name": "auto-bulkWrite",
      "description": "向指定USB端点执行批量写入。",
      "description_en": "Perform a bulk write to the specified USB endpoint."
    },
    {
      "action_name": "auto-bulkRead",
      "description": "从指定USB端点执行批量读取。",
      "description_en": "Perform a bulk read from the specified USB endpoint."
    },
    {
      "action_name": "auto-interruptWrite",
      "description": "向指定USB端点执行中断写入。",
      "description_en": "Perform an interrupt write to the specified USB endpoint."
    },
    {
      "action_name": "auto-interruptRead",
      "description": "从指定USB端点执行中断读取。",
      "description_en": "Perform an interrupt read from the specified USB endpoint."
    },
    {
      "action_name": "auto-controlMsg",
      "description": "通过默认控制通道发送USB控制请求。",
      "description_en": "Send a USB control request through the default control pipe."
    },
    {
      "action_name": "auto-clearHalt",
      "description": "清除指定USB端点的暂停状态。",
      "description_en": "Clear the halt condition on the specified USB endpoint."
    },
    {
      "action_name": "auto-claimInterface",
      "description": "声明并占用指定USB接口。",
      "description_en": "Claim the specified USB interface."
    },
    {
      "action_name": "auto-releaseInterface",
      "description": "释放先前占用的USB接口。",
      "description_en": "Release a previously claimed USB interface."
    },
    {
      "action_name": "auto-reset",
      "description": "复位USB设备。",
      "description_en": "Reset the USB device."
    },
    {
      "action_name": "auto-resetEndpoint",
      "description": "复位指定USB端点的状态。",
      "description_en": "Reset the state of the specified USB endpoint."
    },
    {
      "action_name": "auto-setConfiguration",
      "description": "设置USB设备的活动配置。",
      "description_en": "Set the active configuration of the USB device."
    },
    {
      "action_name": "auto-setAltInterface",
      "description": "设置当前USB接口的备用设置。",
      "description_en": "Set the alternate setting of the current USB interface."
    },
    {
      "action_name": "auto-getString",
      "description": "读取USB设备的字符串描述符。",
      "description_en": "Read a string descriptor from the USB device."
    },
    {
      "action_name": "auto-getDescriptor",
      "description": "读取USB设备的指定描述符。",
      "description_en": "Read a specified descriptor from the USB device."
    },
    {
      "action_name": "auto-detachKernelDriver",
      "description": "从指定USB接口分离操作系统内核驱动。",
      "description_en": "Detach the operating system kernel driver from the specified USB interface."
    }
  ]
}

